do $do$ declare d jsonb := $j${"topic": {"id": "c55b6d46-06cb-500f-aae1-cbb209a613e6", "new": true, "name": "Biology · Ecosystems", "summary": "Grade 10 Biology", "sort": 2, "parent": "023f4e76-48bf-5493-80d8-ef40cc04f570", "programme": "MYP 5"}, "anchor": "/g10-bio-classification-5/", "lessons": [{"id": "f0b88bb7-a044-553a-ae39-b6090073068b", "ext": "G10-BIO-ECOSYSTEMS-L1", "title": "Biology · Ecosystems · Lesson 1: Ecosystems, species, populations and communities", "summary": "MYP 5 · Biology · Ecosystems", "url": "/g10-bio-ecosystems-1/", "max": 33, "sort": 11, "msort": 543, "csort": 72, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 6, "n": 6, "ans": ["An ecosystem", "An ecosystem", "Not an ecosystem", "Not an ecosystem", "An ecosystem", "Not an ecosystem"], "tip": "An ecosystem needs living things AND their non-living surroundings, interacting."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Salty, alkaline water", "Warm, shallow seawater", "Seasonal rain and open grassland", "High rainfall all year", "Cold, high altitude"], "tip": "Think about the water, the rain and the temperature in each place."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["different habitat", "more habitat", "many habitat", "different conditions", "different abiotic", "different environment"], ["adapted", "different species", "different communit", "more species", "niche"]], "tips": ["Different places, different conditions…"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 6, "n": 6, "ans": ["Organism", "Population", "Community", "Ecosystem", "Population", "Community"], "tip": "Population = one species. Community = many species. Ecosystem = community + abiotic environment."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 3, "pts": [["one species", "same species", "single species"], ["different species", "many species", "all the species", "all species", "several species"], ["flamingo", "zebra", "wildebeest", "lion", "tilapia", "buffalo", "acacia", "example"]], "tips": ["One species or many? Then name a real example."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 3, "pts": [["different species", "many species", "more than one species", "several species", "flamingos and pelicans", "not one species", "not the same species"], ["population", "one species", "same species", "single species"], ["community"]], "tips": ["How many species of bird live at the lake?"]}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 3, "pts": [["abiotic", "non-living", "environment", "physical"], ["light", "water", "temperature", "soil", "air", "oxygen", "mineral", "salt", "rain", "wind", "ph"], ["light", "water", "temperature", "soil", "air", "oxygen", "mineral", "salt", "rain", "wind", "ph"]], "tips": ["Living + …?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 3, "pts": [["25", "total"], ["5 per", "mean 5", "mean is 5", "average 5", "25/5", "25 ÷ 5", "= 5"], ["1000", "1 000", "1,000"]], "tips": ["Find the mean per quadrat first, then multiply by the number of 1 m² squares in the plot."]}, {"kind": "text", "id": "q5_1", "q": "Q10", "max": 2, "pts": [["more quadrats", "more samples", "larger sample", "repeat", "increase the number"], ["random", "randomly", "grid", "coordinates", "avoid bias", "not chosen", "whole plot", "spread"]], "tips": ["Think about how many samples and how they are chosen."]}]}, "models": {"1": [["Q1", "Living: flamingos, algae, buffalo. Non-living: salty water, sunlight. They are studied together because they affect each other: the algae need sunlight and the salty water, the flamingos need the algae."], ["Q2", "An ecosystem has a community of living things and the abiotic environment they interact with. One organism, or one herd on its own, is not an ecosystem; sand with no life has no community."]], "2": [["Q3", "Each ecosystem has different abiotic conditions, so each supports a different community: this is why Kenya has high ecosystem diversity."], ["Q4", "Different ecosystems provide different habitats and conditions [1], each with species adapted to it, so there are more species overall [1]."]], "3": [["Q5", "Organism: one individual. Population: one species in one area. Community: all the species in one area. Ecosystem: the community and its abiotic environment."], ["Q6", "A population is all the organisms of one species in an area [1]; a community is all the populations of different species in that area [1]; e.g. all the flamingos at Lake Nakuru are a population, while the flamingos, pelicans, algae and fish together are a community [1]."]], "4": [["Q7", "The birds belong to several different species (flamingos, pelicans, storks) [1]; a population contains only one species [1]; all the birds together are part of the community (or a group of populations) [1]."], ["Q8", "The abiotic (non-living) environment [1], for example light and water (any two: light, water, temperature, soil, minerals, air, pH) [2]."]], "5": [["Q9", "Total = 4 + 6 + 3 + 5 + 7 = 25 [1]; mean = 25 ÷ 5 = 5 seedlings per m² [1]; estimate = 5 × 200 = 1000 seedlings [1]."], ["Q10", "Use more quadrats [1]; place them randomly (for example with random coordinates) so the samples are not biased [1]."]], "6": [["Exit ticket", "A population is one species in an area; a community is all the populations of different species in that area."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_1": "Q6", "q4_0": "Q7", "q4_1": "Q8", "q5_0": "Q9", "q5_1": "Q10", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "df867cc9-3dde-5f62-8fe1-aea3011de202", "ext": "G10-BIO-ECOSYSTEMS-L2", "title": "Biology · Ecosystems · Lesson 2: Biotic and abiotic factors and how they interact", "summary": "MYP 5 · Biology · Ecosystems", "url": "/g10-bio-ecosystems-2/", "max": 45, "sort": 12, "msort": 544, "csort": 73, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 10, "n": 10, "ans": ["Abiotic", "Biotic", "Abiotic", "Biotic", "Abiotic", "Biotic", "Abiotic", "Biotic", "Abiotic", "Abiotic"], "tip": "Is it alive, or caused directly by something alive?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 8, "n": 8, "ans": ["Predation", "Competition", "Parasitism", "Mutualism", "Mutualism", "Competition", "Parasitism", "Predation"], "tip": "Who benefits and who is harmed?"}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["predat", "lion", "hyena", "crocodile", "leopard"], ["competition", "compete", "disease", "parasite", "tick", "wildebeest", "less grass", "food"]], "tips": ["Think of what eats zebras and what they compete with."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 6, "n": 6, "ans": ["Light meter", "Thermometer", "Rain gauge", "pH meter or universal indicator", "Anemometer", "Oxygen probe"], "tip": "Match the quantity to the tool."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 4, "pts": [["salt", "saline", "salinity"], ["alkaline", "ph", "soda"], ["temperature", "warm", "light", "sunlight", "water level", "rainfall", "depth"], ["algae", "spirulina", "arthrospira", "flamingo", "few species", "only some", "specialised", "adapted"]], "tips": ["Name three non-living conditions, then link one to a living thing."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 4, "pts": [["rain", "water"], ["grow", "photosynthes", "more grass", "grass grows"], ["wildebeest", "herbivore", "zebra", "food for", "migrat"], ["lion", "predator", "crocodile", "hyena", "more prey", "food chain", "food web"]], "tips": ["Rain → plants → herbivores → …"]}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 4, "pts": [["shade", "less light", "block light", "reduce light", "lower light"], ["cooler", "lower temperature", "temperature", "humid", "moisture", "less evaporation"], ["leaves fall", "leaf litter", "decompos", "mineral", "nutrient", "humus"], ["roots", "erosion", "hold the soil", "soil structure", "oxygen", "carbon dioxide"]], "tips": ["Think of light, temperature, water and soil under a tree."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["decrease", "falls", "goes down", "less", "lower"], ["fewer grass", "grass decreases", "number of grass", "grass falls", "both decrease", "both fall", "fewer plants"], ["photosynthes"], ["shade", "tree", "canopy", "less light", "cannot make", "less glucose", "less food", "slower growth", "compete"]], "tips": ["What happens to each as you go into the forest, and why does light matter to grass?"]}, {"kind": "text", "id": "q5_1", "q": "Q9", "max": 3, "pts": [["temperature", "humidity", "soil moisture", "moisture", "water", "soil ph", "mineral", "nutrient", "wind"], ["not the only", "other factor", "also", "more than one", "correlation", "not proof", "cannot be sure", "competition", "grazing"], ["control", "measure", "experiment", "test", "investigate", "shade", "fair test"]], "tips": ["Light is not the only thing that changes under trees…"]}]}, "models": {"1": [["Q1", "Biotic: grass, lions hunting, bacteria, ticks. Abiotic: sunlight, temperature, soil pH, rainfall, wind, salinity."]], "2": [["Q2", "Predation: one kills and eats the other. Competition: both need the same limited resource. Parasitism: one benefits, the host is harmed. Mutualism: both benefit."], ["Q3", "More predators such as lions eating zebras [1]; competition with wildebeest for grass, or disease/parasites (any one) [1]."]], "3": [["Q4", "Light meter: light intensity. Thermometer: temperature. Rain gauge: rainfall. pH meter or universal indicator: pH. Anemometer: wind speed. Oxygen probe: dissolved oxygen."], ["Q5", "Abiotic factors: high salinity [1], high (alkaline) pH [1], warm temperature / bright sunlight / water level (any one) [1]; e.g. the salty alkaline water allows only specialised algae such as spirulina to grow, which feed the flamingos [1]."]], "4": [["Q6", "Rain provides water for the grass [1], so it photosynthesises and grows quickly [1]; this provides food, so herbivores such as wildebeest move in and their numbers rise [1]; predators such as lions then have more prey [1]."], ["Q7", "Trees shade the ground [1], so there is less light and a lower temperature / higher humidity below [1]; their fallen leaves decompose and add minerals (humus) to the soil [1], and their roots hold the soil and reduce erosion (or photosynthesis changes the air) [1]."]], "5": [["Q8", "As distance into the forest increases, light intensity decreases [1] and the number of grass plants decreases [1]; grass needs light for photosynthesis [1], so under the shade of the tree canopy it cannot make enough glucose to grow (trees out-compete it for light) [1]."], ["Q9", "e.g. humidity / temperature / soil moisture also changes [1]; light may not be the only cause, as competition from tree roots or other abiotic factors could also reduce grass; the data show a correlation, not proof [1]; to test light alone, grow grass in different light intensities with other factors controlled [1]."]], "6": [["Exit ticket", "Less light on a forest floor means fewer plants grow; trees shade the ground and so lower the light intensity and temperature beneath them."]]}, "labels": {"q2_1": "Q3", "q3_1": "Q5", "q4_0": "Q6", "q4_1": "Q7", "q5_0": "Q8", "q5_1": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "bbedbe51-49a2-5662-8e30-7e88711181c1", "ext": "G10-BIO-ECOSYSTEMS-L3", "title": "Biology · Ecosystems · Lesson 3: Biodiversity, its conservation, biomes, habitats and niches", "summary": "MYP 5 · Biology · Ecosystems", "url": "/g10-bio-ecosystems-3/", "max": 37, "sort": 13, "msort": 545, "csort": 74, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Genetic diversity", "Species diversity", "Ecosystem diversity", "Genetic diversity", "Species diversity"], "tip": "Variety within a species, between species, or between ecosystems?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 6, "n": 6, "ans": ["In-situ", "Ex-situ", "In-situ", "Ex-situ", "In-situ", "Ex-situ"], "tip": "Is the species protected where it naturally lives?"}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 4, "pts": [["natural habitat", "where it lives", "in the wild", "on site"], ["outside", "zoo", "seed bank", "orphanage", "captive", "laboratory", "off site"], ["whole ecosystem", "natural behaviour", "many species", "cheaper", "interact"], ["protected from", "safe from", "poach", "breed", "back-up", "very rare", "few individuals", "last", "store"]], "tips": ["Where? Then one advantage each."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 5, "n": 5, "ans": ["Desert", "Savanna", "Tropical rainforest", "Tundra or alpine", "Coral reef (marine)"], "tip": "Look at the rainfall and the vegetation."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 3, "pts": [["wet", "dry season", "warm", "hot", "seasonal"], ["grass", "scattered trees", "acacia"], ["mara", "tsavo", "amboseli", "samburu", "serengeti", "nairobi national park", "laikipia", "meru"]], "tips": ["Climate, plants, place."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 6, "n": 6, "ans": ["Habitat", "Niche", "Habitat", "Niche", "Niche", "Habitat"], "tip": "A place, or a role?"}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 4, "pts": [["habitat", "where", "place", "lives"], ["river", "lake", "water"], ["niche", "role", "way of life", "job"], ["graz", "grass", "dung", "night", "nutrients", "eats"]], "tips": ["Define both, then the hippo example for each."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 4, "pts": [["income", "jobs", "money", "benefit", "tourism", "share"], ["protect", "less poaching", "rangers", "wildlife", "support", "involve"], ["grazing", "land", "conflict", "drought", "tourism falls", "covid", "unequal", "elite", "livestock", "limitation"], ["i think", "overall", "conclusion", "therefore", "should"]], "tips": ["Strength, limitation, conclusion."]}]}, "models": {"1": [["Q1", "A school compound may have grass, a few trees, birds, insects, spiders and fungi. Kakamega Forest is a large, old, undisturbed rainforest with many habitats and niches, so it holds hundreds of tree, bird, butterfly and primate species: much higher biodiversity."], ["Q2", "Varieties within one species: genetic. Number of species: species. Different kinds of ecosystem: ecosystem diversity."]], "2": [["Q3", "Parks, marine parks and conservancies: in-situ. Seed banks, frozen eggs and captive breeding: ex-situ."], ["Q4", "In-situ conservation protects species in their natural habitat [1], while ex-situ conservation keeps them outside it, for example in a seed bank or captive breeding centre [1]; in-situ protects the whole ecosystem and natural behaviour of many species at once [1]; ex-situ keeps very rare species safe from poaching and can breed them as a back-up [1]."]], "3": [["Q5", "Dry: desert. Grass and scattered trees: savanna. Hot and wet with layered trees: rainforest. Cold with mosses: tundra. Warm shallow sea: coral reef."], ["Q6", "The savanna is warm all year with a wet season and a long dry season [1]; the vegetation is grassland with scattered trees such as acacias [1]; it is found in the Maasai Mara (or Tsavo, Amboseli) [1]."]], "4": [["Q7", "Places are habitats; what an organism does, eats and is eaten by is its niche."], ["Q8", "A habitat is the place where an organism lives [1]: for a hippo, a river or lake with grassland nearby [1]; a niche is its role and way of life in the ecosystem [1]: the hippo grazes grass at night, rests in water by day, and its dung adds nutrients to the water for fish [1]."]], "5": [["Q9", "A strength is that local people earn income and jobs from tourism [1], so they have a reason to protect wildlife and report poachers [1]; a limitation is that herders may lose grazing land, causing conflict, especially in droughts, and income falls when tourism falls [1]; overall I think conservancies work well if the money is shared fairly and grazing rules are agreed with the community [1]."]], "6": [["Exit ticket", "Biodiversity is the variety of life at genetic, species and ecosystem level; a niche is the role and way of life of a species; savanna (Maasai Mara)."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_1": "Q6", "q4_1": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "c6bda871-2c4f-5e14-a66e-334b638dc57b", "ext": "G10-BIO-ECOSYSTEMS-L4", "title": "Biology · Ecosystems · Lesson 4: Food chains, food webs and energy flow (the 10% law)", "summary": "MYP 5 · Biology · Ecosystems", "url": "/g10-bio-ecosystems-4/", "max": 21, "sort": 14, "msort": 546, "csort": 75, "spec": {"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 3, "pts": [["algae producer", "producer algae", "algae level 1", "algae trophic level 1"], ["small fish primary", "small fish level 2", "small fish trophic level 2", "primary consumer small fish"], ["pelican tertiary", "pelican level 4", "pelican trophic level 4", "tertiary consumer pelican"]], "tips": ["Producer first, then follow \"is eaten by\"."]}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 2, "pts": [["photosynth", "make their own food", "makes its own food"], ["light", "sun", "energy", "chemical"]], "tips": ["Where does the energy enter the chain?"]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 4, "pts": [["grass → zebra", "grass -> zebra", "grass zebra lion", "grass → zebra → lion", "grass zebra hyena"], ["acacia → giraffe", "acacia -> giraffe", "acacia giraffe", "acacia → gazelle", "acacia gazelle"], ["grasshopper → roller", "grasshopper -> roller", "grass grasshopper roller", "grasshopper roller", "grasshopper bird", "gazelle cheetah", "gazelle → cheetah"], ["two chains", "grass → gazelle → cheetah", "grass gazelle cheetah", "grass → zebra → hyena", "grass zebra hyena", "grass gazelle hyena", "grass → gazelle → hyena"]], "tips": ["Draw the producers first, then add the arrows."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 3, "pts": [["respiration", "heat", "movement", "warm"], ["not eaten", "bones", "hooves", "skin", "hair", "left"], ["faeces", "egest", "not digested", "urine", "urea", "excret", "dung"]], "tips": ["Used, left, passed out."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["5000", "5 000", "5,000"], ["500"]], "tips": ["Multiply by 0.1 at each step."]}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 3, "pts": [["2400 ÷ 30000", "2 400 ÷ 30 000", "2400/30000", "2400 / 30000", "0.08"], ["8"], ["less", "lower", "below", "smaller"]], "tips": ["Efficiency = (energy passed on ÷ energy available) × 100."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 4, "pts": [["3 million", "3 000 000", "3,000,000", "3000000"], ["less energy", "90%", "lost", "more people", "ten times"], ["protein", "iron", "nutrients", "grass", "land", "pastoral", "cannot grow crops", "arid", "income", "culture"], ["i think", "overall", "conclusion", "should", "balance"]], "tips": ["Multiply by 0.1, then argue both sides."]}]}, "models": {"1": [["Q1", "Algae (producer, trophic level 1) → [1] small fish (primary consumer, level 2) → tilapia (secondary consumer, level 3) → [1] pelican (tertiary consumer, level 4) [1]."], ["Q2", "Producers make their own food by photosynthesis [1]; they convert light energy from the Sun into chemical energy that all other organisms in the chain depend on [1]."]], "2": [["Q3", "Web: grass → zebra, gazelle, grasshopper; acacia → giraffe, gazelle; grasshopper → roller; zebra → lion, hyena; gazelle → cheetah, hyena [1] (grass → zebra → lion) [1] (acacia → giraffe) [1]; two chains: grass → gazelle → cheetah and grass → zebra → hyena [1]."]], "3": [["Q4", "The zebra used much of its energy in respiration for movement and keeping warm, lost as heat [1]; the lion does not eat all of the zebra: bones, hooves and skin are left [1]; some of what the lion eats is not digested and leaves in faeces, and some leaves as urea in urine [1]."]], "4": [["Q5", "(a) Zebras: 50 000 × 0.1 = 5 000 kJ [1]; (b) lions: 5 000 × 0.1 = 500 kJ [1]."], ["Q6", "Efficiency = 2 400 ÷ 30 000 [1] × 100 = 8% [1]; this is a little lower than the 10% predicted by the 10% law [1]."]], "5": [["Q7", "Beef from 1 hectare: 30 million × 0.1 = 3 million kJ [1]; eating the maize directly gives ten times more energy, because 90% is lost in the cattle, so the same land could feed more people [1]; however, meat provides protein and iron, and many pastoral areas in Kenya are too dry for crops but can support livestock on grass [1]; overall I think people in farming areas could eat more plant foods, but livestock remains important where crops cannot grow [1]."]], "6": [["Exit ticket", "Grass → zebra → lion; about 10% of 10% = 1% of the grass energy reaches the lion."]]}, "labels": {"q1_0": "Q1", "q1_1": "Q2", "q2_0": "Q3", "q3_0": "Q4", "q4_0": "Q5", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}], "quizzes": [{"id": "6eb1e987-3646-5974-a14d-b2ef10d7b5a2", "title": "Grade 10 · Biology · Ecosystems · Lesson 1: Ecosystems, species, populations and communities · Criteria A and C exam-style questions", "instr": "Exam-style questions for the lesson \"Ecosystems, species, populations and communities\" (MYP 5, Grade 10 Biology). Criterion A: Knowing and understanding. Criterion C: Processing and evaluating. 12 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark."}, {"id": "a681e3bf-1635-5fa2-8b73-2ee4e5ea8a73", "title": "Grade 10 · Biology · Ecosystems · Lesson 2: Biotic and abiotic factors and how they interact · Criteria A, C and D exam-style questions", "instr": "Exam-style questions for the lesson \"Biotic and abiotic factors and how they interact\" (MYP 5, Grade 10 Biology). Criterion A: Knowing and understanding. Criterion C: Processing and evaluating. Criterion D: Reflecting on the impacts of science. 17 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark."}, {"id": "7cb32e5f-7861-537e-80de-105c3659d1fb", "title": "Grade 10 · Biology · Ecosystems · Lesson 3: Biodiversity, its conservation, biomes, habitats and niches · Criteria A and D exam-style questions", "instr": "Exam-style questions for the lesson \"Biodiversity, its conservation, biomes, habitats and niches\" (MYP 5, Grade 10 Biology). Criterion A: Knowing and understanding. Criterion D: Reflecting on the impacts of science. 19 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark."}, {"id": "355d71c0-57fb-58c9-81b6-27740eb5dd78", "title": "Grade 10 · Biology · Ecosystems · Lesson 4: Food chains, food webs and energy flow (the 10% law) · Criteria A, C and D exam-style questions", "instr": "Exam-style questions for the lesson \"Food chains, food webs and energy flow (the 10% law)\" (MYP 5, Grade 10 Biology). Criterion A: Knowing and understanding. Criterion C: Processing and evaluating. Criterion D: Reflecting on the impacts of science. 17 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark."}], "questions": [{"id": "34b68c87-7a07-5259-a9a8-afa0eae64278", "quiz": "6eb1e987-3646-5974-a14d-b2ef10d7b5a2", "pos": 1, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nDefine the term ecosystem.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "A community of living organisms [1] interacting with each other and with their non-living (abiotic) environment [1].", "points": [{"text": "A community of living organisms", "any": ["communit", "living organisms", "living things", "organisms", "biotic"], "all": [], "marks": 1}, {"text": "Interacting with each other and with their non-living (abiotic) environment", "any": ["abiotic", "non-living", "environment", "surroundings", "physical"], "all": [], "marks": 1}]}, {"id": "08875e41-3c56-5403-9632-4a82bed1aec8", "quiz": "6eb1e987-3646-5974-a14d-b2ef10d7b5a2", "pos": 2, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nDescribe what is meant by ecosystem diversity and give two examples of different ecosystems found in one country.", "options": [], "marks": 3, "section": "Criterion A", "correct": null, "model": "Ecosystem diversity is the variety of different ecosystems (habitats and their communities) in an area [1]; e.g. coral reef and savanna grassland (any two different ecosystems) [2].", "points": [{"text": "Marking point 1", "any": ["variety of ecosystem", "variety of different ecosystem", "different ecosystems", "number of ecosystems", "range of ecosystems", "variety of habitat"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["coral reef", "mangrove", "savanna", "grassland", "rainforest", "forest", "lake", "desert", "moorland", "river", "wetland", "ocean"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["coral reef", "mangrove", "savanna", "grassland", "rainforest", "forest", "lake", "desert", "moorland", "river", "wetland", "ocean"], "all": [], "marks": 1}]}, {"id": "a7a68fc8-a7d5-5cea-b37b-2a9e99bc99a1", "quiz": "6eb1e987-3646-5974-a14d-b2ef10d7b5a2", "pos": 3, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nIn the Maasai Mara there are wildebeest, zebras, lions and red oat grass. Using these organisms, describe a species, a population and a community.", "options": [], "marks": 3, "section": "Criterion A", "correct": null, "model": "Species: e.g. wildebeest, organisms that can interbreed to produce fertile offspring [1]; population: all the wildebeest (one species) living in the Maasai Mara [1]; community: the wildebeest, zebras, lions and grass populations living together [1].", "points": [{"text": "Species: e.g. wildebeest, organisms that can interbreed to produce fertile offspring", "any": ["interbreed", "fertile", "breed together"], "all": [], "marks": 1}, {"text": "Population: all the wildebeest (one species) living in the Maasai Mara", "any": ["all the", "one species", "same species"], "all": [], "marks": 1}, {"text": "Community: the wildebeest, zebras, lions and grass populations living together", "any": ["different species", "all the populations", "together", "wildebeest, zebras", "all of them"], "all": [], "marks": 1}]}, {"id": "4661d65f-186c-5bbb-90b5-73cd265b0b7f", "quiz": "6eb1e987-3646-5974-a14d-b2ef10d7b5a2", "pos": 4, "kind": "short", "prompt": "[Criterion C: Processing and evaluating]\nA student counts Thomson's gazelles in four 1 km² sample areas of a 60 km² reserve: 12, 8, 15 and 9. Estimate the population of gazelles in the reserve and state one assumption you made.", "options": [], "marks": 4, "section": "Criterion C", "correct": null, "model": "Total = 44 [1]; mean = 11 per km² [1]; estimate = 11 × 60 = 660 gazelles [1]; assumption: the sample areas are representative / the gazelles are spread evenly / no gazelle was counted twice [1].", "points": [{"text": "Total = 44", "any": ["44"], "all": [], "marks": 1}, {"text": "Mean = 11 per km²", "any": ["11"], "all": [], "marks": 1}, {"text": "Estimate = 11 × 60 = 660 gazelles", "any": ["660"], "all": [], "marks": 1}, {"text": "Assumption: the sample areas are representative / the gazelles are spread evenly / no gazelle was counted twice", "any": ["evenly", "same density", "representative", "random", "do not move", "not counted twice", "typical", "uniform"], "all": [], "marks": 1}]}, {"id": "7bf99b84-270a-59f0-9d5c-d650d0891e12", "quiz": "a681e3bf-1635-5fa2-8b73-2ee4e5ea8a73", "pos": 1, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nState the difference between a biotic factor and an abiotic factor, and give one example of each.", "options": [], "marks": 3, "section": "Criterion A", "correct": null, "model": "Biotic factors are living (or caused by living things) [1]; abiotic factors are non-living physical or chemical conditions [1]; e.g. biotic: predation by lions; abiotic: light intensity [1].", "points": [{"text": "Biotic factors are living (or caused by living things)", "any": ["living"], "all": [], "marks": 1}, {"text": "Abiotic factors are non-living physical or chemical conditions", "any": ["non-living", "nonliving", "not living", "physical", "chemical"], "all": [], "marks": 1}, {"text": "E.g. biotic: predation by lions; abiotic: light intensity", "any": ["light", "temperature", "water", "rain", "ph", "soil", "wind", "oxygen", "salinity", "predat", "competi", "disease", "parasit", "decomposer"], "all": [], "marks": 1}]}, {"id": "0d194e9b-5917-54c2-b012-874947052eb5", "quiz": "a681e3bf-1635-5fa2-8b73-2ee4e5ea8a73", "pos": 2, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nDescribe two types of biotic interaction, using a different example for each.", "options": [], "marks": 4, "section": "Criterion A", "correct": null, "model": "Any two, each named and described [1 + 1] with an example [1 + 1]: predation, one animal kills and eats another (lion and zebra); competition for a limited resource (lions and hyenas for prey); parasitism, one lives on a host and harms it (ticks on cattle); mutualism, both benefit (ants and whistling-thorn acacia).", "points": [{"text": "Marking point 1", "any": ["predation", "predator", "competition", "compete", "parasit", "mutualism", "both benefit"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["kills", "eats", "same resource", "limited", "harm", "host", "both benefit", "benefit"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["lion", "zebra", "tick", "bee", "ant", "acacia", "hyena", "cheetah", "tapeworm", "oxpecker", "buffalo", "cattle"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["lion", "zebra", "tick", "bee", "ant", "acacia", "hyena", "cheetah", "tapeworm", "oxpecker", "buffalo", "cattle"], "all": [], "marks": 1}]}, {"id": "590d4c32-1ef8-582d-9426-eb22b583918d", "quiz": "a681e3bf-1635-5fa2-8b73-2ee4e5ea8a73", "pos": 3, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nExplain how temperature can affect the organisms of a coral reef.", "options": [], "marks": 3, "section": "Criterion A", "correct": null, "model": "A rise in sea temperature [1] causes corals to lose the algae living in them (bleaching) [1]; the corals may die, so fish and other species that depend on the reef for food and shelter decline [1].", "points": [{"text": "Marking point 1", "any": ["warm", "higher temperature", "temperature rise", "heat"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["bleach", "lose algae", "algae leave", "expel"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["die", "death", "fish", "food", "habitat", "other species", "decline"], "all": [], "marks": 1}]}, {"id": "6a03af53-7b96-5f0b-b526-e6ee2f97cbfb", "quiz": "a681e3bf-1635-5fa2-8b73-2ee4e5ea8a73", "pos": 4, "kind": "short", "prompt": "[Criterion C: Processing and evaluating]\nLight intensity under an acacia tree is 8 000 lux and in the open grassland 40 000 lux. Calculate how many times brighter the open grassland is, and explain one effect this difference could have on the plants under the tree.", "options": [], "marks": 3, "section": "Criterion C", "correct": null, "model": "40 000 ÷ 8 000 = 5 times brighter [1]; less light under the tree means less photosynthesis [1], so fewer grass plants grow / only shade-tolerant plants survive there [1].", "points": [{"text": "40 000 ÷ 8 000 = 5 times brighter", "any": ["5"], "all": [], "marks": 1}, {"text": "Less light under the tree means less photosynthesis", "any": ["less photosynthesis", "photosynthesis", "slower growth", "less growth", "fewer plants"], "all": [], "marks": 1}, {"text": "Fewer grass plants grow / only shade-tolerant plants survive there", "any": ["shade tolerant", "large leaves", "different species", "fewer grass", "cannot grow", "less glucose"], "all": [], "marks": 1}]}, {"id": "9d084d58-c45e-53ec-842b-33a496a118ef", "quiz": "a681e3bf-1635-5fa2-8b73-2ee4e5ea8a73", "pos": 5, "kind": "short", "prompt": "[Criterion D: Reflecting on the impacts of science]\nIn parts of Laikipia, the ants that defend whistling-thorn acacias have been displaced by an invasive ant species that does not defend the trees. Discuss how this could affect the ecosystem, including the abiotic factors.", "options": [], "marks": 4, "section": "Criterion D", "correct": null, "model": "Without defending ants, elephants and other browsers eat and push over more acacias [1], so tree cover falls [1]; more light reaches the ground and the soil becomes hotter and drier / more erosion (abiotic change) [1]; the community changes: more grass but fewer animals that depend on the trees for food or shelter (e.g. giraffes, birds) [1].", "points": [{"text": "Without defending ants, elephants and other browsers eat and push over more acacias", "any": ["elephant", "browse", "eaten", "damage", "destroy", "knocked down", "pushed over"], "all": [], "marks": 1}, {"text": "Tree cover falls", "any": ["fewer trees", "trees die", "less tree", "loss of trees", "tree cover"], "all": [], "marks": 1}, {"text": "More light reaches the ground and the soil becomes hotter and drier / more erosion (abiotic change)", "any": ["more light", "less shade", "temperature", "drier", "soil", "erosion", "humidity"], "all": [], "marks": 1}, {"text": "The community changes: more grass but fewer animals that depend on the trees for food or shelter (e.g. giraffes, birds)", "any": ["grass", "community", "species", "animals that", "food chain", "food web", "habitat", "giraffe", "birds"], "all": [], "marks": 1}]}, {"id": "012321d6-7f34-58e1-beb5-2d020e58fe10", "quiz": "7cb32e5f-7861-537e-80de-105c3659d1fb", "pos": 1, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nDefine biodiversity and state its three levels.", "options": [], "marks": 4, "section": "Criterion A", "correct": null, "model": "Biodiversity is the variety of life in an area or on Earth [1]; at the level of genetic diversity [1], species diversity [1] and ecosystem diversity [1].", "points": [{"text": "Biodiversity is the variety of life in an area or on Earth", "any": ["variety", "range", "different"], "all": [], "marks": 1}, {"text": "At the level of genetic diversity", "any": ["genetic"], "all": [], "marks": 1}, {"text": "Species diversity", "any": ["species"], "all": [], "marks": 1}, {"text": "Ecosystem diversity", "any": ["ecosystem", "habitat"], "all": [], "marks": 1}]}, {"id": "7aa260fb-ab3d-5b21-ba98-fe6e778f6052", "quiz": "7cb32e5f-7861-537e-80de-105c3659d1fb", "pos": 2, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nDefine conservation of biodiversity.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "The protection, management and restoration of species and ecosystems [1] so that the variety of life survives for future generations [1].", "points": [{"text": "The protection, management and restoration of species and ecosystems", "any": ["protect", "manage", "preserv", "restor"], "all": [], "marks": 1}, {"text": "That the variety of life survives for future generations", "any": ["future", "survive", "species", "ecosystem", "variety"], "all": [], "marks": 1}]}, {"id": "663676c1-9b7f-5c95-9773-6373bc1d7605", "quiz": "7cb32e5f-7861-537e-80de-105c3659d1fb", "pos": 3, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nIn-situ or ex-situ?\nTsavo East National Park", "options": ["In-situ", "Ex-situ"], "marks": 1, "section": "Criterion A", "correct": 0, "model": "Parks are in-situ; seed banks and captive breeding are ex-situ.", "points": null}, {"id": "6d9b9fa1-05df-58ba-a680-d08025779350", "quiz": "7cb32e5f-7861-537e-80de-105c3659d1fb", "pos": 4, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nIn-situ or ex-situ?\nA seed bank", "options": ["In-situ", "Ex-situ"], "marks": 1, "section": "Criterion A", "correct": 1, "model": "Parks are in-situ; seed banks and captive breeding are ex-situ.", "points": null}, {"id": "51726092-7f9f-54e5-bb4b-0e8ac5da9973", "quiz": "7cb32e5f-7861-537e-80de-105c3659d1fb", "pos": 5, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nIn-situ or ex-situ?\nA marine national park", "options": ["In-situ", "Ex-situ"], "marks": 1, "section": "Criterion A", "correct": 0, "model": "Parks are in-situ; seed banks and captive breeding are ex-situ.", "points": null}, {"id": "427cb6a1-05c4-5895-9257-c50c05873586", "quiz": "7cb32e5f-7861-537e-80de-105c3659d1fb", "pos": 6, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nIn-situ or ex-situ?\nCaptive breeding in an animal orphanage", "options": ["In-situ", "Ex-situ"], "marks": 1, "section": "Criterion A", "correct": 1, "model": "Parks are in-situ; seed banks and captive breeding are ex-situ.", "points": null}, {"id": "2646ae8a-8260-5405-bed0-149ad9b8edc5", "quiz": "7cb32e5f-7861-537e-80de-105c3659d1fb", "pos": 7, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nWhich biome?\nHot and wet all year, tall evergreen trees", "options": ["Tropical rainforest", "Savanna", "Desert", "Tundra"], "marks": 1, "section": "Criterion A", "correct": 0, "model": "Rainforest; savanna; desert; tundra.", "points": null}, {"id": "227e3671-7187-5946-92ca-303973c34a1f", "quiz": "7cb32e5f-7861-537e-80de-105c3659d1fb", "pos": 8, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nWhich biome?\nGrassland with scattered trees and a dry season", "options": ["Tropical rainforest", "Savanna", "Desert", "Tundra"], "marks": 1, "section": "Criterion A", "correct": 1, "model": "Rainforest; savanna; desert; tundra.", "points": null}, {"id": "13a2d66b-4dd3-5e9a-bd5d-3c194acf4fc8", "quiz": "7cb32e5f-7861-537e-80de-105c3659d1fb", "pos": 9, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nWhich biome?\nVery low rainfall, succulent plants", "options": ["Tropical rainforest", "Savanna", "Desert", "Tundra"], "marks": 1, "section": "Criterion A", "correct": 2, "model": "Rainforest; savanna; desert; tundra.", "points": null}, {"id": "253fa2d9-4db7-5bbd-a7b6-6ce4edd2438e", "quiz": "7cb32e5f-7861-537e-80de-105c3659d1fb", "pos": 10, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nWhich biome?\nFrozen subsoil, mosses and lichens", "options": ["Tropical rainforest", "Savanna", "Desert", "Tundra"], "marks": 1, "section": "Criterion A", "correct": 3, "model": "Rainforest; savanna; desert; tundra.", "points": null}, {"id": "4979ed2c-79d4-54e5-b402-7366746d5e53", "quiz": "7cb32e5f-7861-537e-80de-105c3659d1fb", "pos": 11, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nDistinguish between a habitat and a niche.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "A habitat is the place where an organism lives [1]; a niche is its role and way of life in the ecosystem [1].", "points": [{"text": "A habitat is the place where an organism lives", "any": ["place where", "where it lives", "where an organism lives", "place it lives", "home"], "all": [], "marks": 1}, {"text": "A niche is its role and way of life in the ecosystem", "any": ["role", "way of life", "job"], "all": [], "marks": 1}]}, {"id": "9f332868-29ae-5d17-ba5c-475a7a1023d6", "quiz": "7cb32e5f-7861-537e-80de-105c3659d1fb", "pos": 12, "kind": "short", "prompt": "[Criterion D: Reflecting on the impacts of science]\nDiscuss whether a seed bank is a better use of money than protecting a forest.", "options": [], "marks": 3, "section": "Criterion D", "correct": null, "model": "A seed bank safely stores the genes of thousands of plant species as a back-up, cheaply [1]; but protecting a forest conserves the whole ecosystem, including animals, and its services such as clean water [1]; overall I think both are needed, but the forest should come first because a seed bank cannot save animals or ecosystem services [1].", "points": [{"text": "A seed bank safely stores the genes of thousands of plant species as a back-up, cheaply", "any": ["seed bank", "store", "many species", "safe", "back-up", "crop", "cheap"], "all": [], "marks": 1}, {"text": "Protecting a forest conserves the whole ecosystem, including animals, and its services such as clean water", "any": ["forest", "whole ecosystem", "animals", "water", "services", "natural", "in-situ"], "all": [], "marks": 1}, {"text": "Overall I think both are needed, but the forest should come first because a seed bank cannot save animals or ecosystem services", "any": ["i think", "both", "overall", "conclusion", "because"], "all": [], "marks": 1}]}, {"id": "79c2816b-9e17-5b1f-9383-e5290abab416", "quiz": "355d71c0-57fb-58c9-81b6-27740eb5dd78", "pos": 1, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nDefine a food chain.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "A sequence of organisms [1] in which each is eaten by the next, showing the transfer of energy [1].", "points": [{"text": "A sequence of organisms", "any": ["sequence", "series", "order", "list"], "all": [], "marks": 1}, {"text": "In which each is eaten by the next, showing the transfer of energy", "any": ["eaten", "eats", "energy", "feeding", "food"], "all": [], "marks": 1}]}, {"id": "a2cd725c-9827-5da4-bfe9-acba11bbffff", "quiz": "355d71c0-57fb-58c9-81b6-27740eb5dd78", "pos": 2, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nDefine a food web.", "options": [], "marks": 1, "section": "Criterion A", "correct": null, "model": "A network of interconnected food chains in an ecosystem [1].", "points": [{"text": "A network of interconnected food chains in an ecosystem", "any": ["network", "interconnected", "linked", "many food chains"], "all": [], "marks": 1}]}, {"id": "2ee60c81-2e69-5521-8262-4655968b51b2", "quiz": "355d71c0-57fb-58c9-81b6-27740eb5dd78", "pos": 3, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nConstruct a food chain with four trophic levels from these organisms and label each level: hawk, maize plant, rat, snake.", "options": [], "marks": 3, "section": "Criterion A", "correct": null, "model": "Maize plant (producer, level 1) → [1] rat (primary consumer, level 2) → [1] snake (secondary consumer, level 3) → hawk (tertiary consumer, level 4) [1].", "points": [{"text": "Maize plant (producer, level 1) →", "any": ["maize plant producer", "maize producer", "maize level 1", "maize plant level 1", "producer maize"], "all": [], "marks": 1}, {"text": "Rat (primary consumer, level 2) →", "any": ["rat primary", "rat level 2", "primary consumer rat"], "all": [], "marks": 1}, {"text": "Snake (secondary consumer, level 3) → hawk (tertiary consumer, level 4)", "any": ["snake secondary", "snake level 3", "hawk tertiary", "hawk level 4", "tertiary consumer hawk"], "all": [], "marks": 1}]}, {"id": "a12cd1fd-1faf-5365-a80d-7e21ecad7020", "quiz": "355d71c0-57fb-58c9-81b6-27740eb5dd78", "pos": 4, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nIn a lake food web, algae are eaten by small fish and insect larvae; insect larvae are eaten by small fish; small fish are eaten by tilapia and kingfishers; tilapia are eaten by fish eagles. Construct the food web and state the number of food chains.", "options": [], "marks": 3, "section": "Criterion A", "correct": null, "model": "Algae → small fish, insect larvae; insect larvae → small fish [1]; small fish → tilapia, kingfisher; tilapia → fish eagle [1]; there are 4 food chains [1].", "points": [{"text": "Algae → small fish, insect larvae; insect larvae → small fish", "any": ["algae → small fish", "algae -> small fish", "algae small fish", "algae → insect larvae", "algae insect"], "all": [], "marks": 1}, {"text": "Small fish → tilapia, kingfisher; tilapia → fish eagle", "any": ["small fish → tilapia", "small fish tilapia", "tilapia → fish eagle", "tilapia fish eagle", "small fish → kingfisher", "small fish kingfisher"], "all": [], "marks": 1}, {"text": "There are 4 food chains", "any": ["4", "four"], "all": [], "marks": 1}]}, {"id": "78607944-c7f3-5cc9-b0a5-d305292cd404", "quiz": "355d71c0-57fb-58c9-81b6-27740eb5dd78", "pos": 5, "kind": "short", "prompt": "[Criterion C: Processing and evaluating]\nProducers in a field contain 80 000 kJ. Use the 10% law to calculate the energy reaching the tertiary consumers. Show your working.", "options": [], "marks": 2, "section": "Criterion C", "correct": null, "model": "80 000 × 0.1 = 8 000 kJ (primary) × 0.1 = 800 kJ (secondary) [1] × 0.1 = 80 kJ (tertiary consumers) [1].", "points": [{"text": "80 000 × 0.1 = 8 000 kJ (primary) × 0.1 = 800 kJ (secondary)", "any": ["8000", "8 000", "800"], "all": [], "marks": 1}, {"text": "× 0.1 = 80 kJ (tertiary consumers)", "any": ["80"], "all": [], "marks": 1}]}, {"id": "299b3c35-aebf-504d-9e4c-f60c5f97a07d", "quiz": "355d71c0-57fb-58c9-81b6-27740eb5dd78", "pos": 6, "kind": "short", "prompt": "[Criterion C: Processing and evaluating]\nGrass stores 20 000 kJ/m²/year; gazelles store 1 600 kJ/m²/year; cheetahs store 96 kJ/m²/year. Calculate the efficiency of each transfer and state which is more efficient.", "options": [], "marks": 3, "section": "Criterion C", "correct": null, "model": "Grass → gazelle: 1 600 ÷ 20 000 × 100 = 8% [1]; gazelle → cheetah: 96 ÷ 1 600 × 100 = 6% [1]; the transfer from grass to gazelle is more efficient [1].", "points": [{"text": "Grass → gazelle: 1 600 ÷ 20 000 × 100 = 8%", "any": ["8"], "all": [], "marks": 1}, {"text": "Gazelle → cheetah: 96 ÷ 1 600 × 100 = 6%", "any": ["6"], "all": [], "marks": 1}, {"text": "The transfer from grass to gazelle is more efficient", "any": ["grass to gazelle", "first", "gazelle", "producer"], "all": [], "marks": 1}]}, {"id": "ac32293f-c913-5f7f-9e41-0269ad2774e4", "quiz": "355d71c0-57fb-58c9-81b6-27740eb5dd78", "pos": 7, "kind": "short", "prompt": "[Criterion D: Reflecting on the impacts of science]\nExplain why only about 10% of the energy in one trophic level is passed to the next.", "options": [], "marks": 3, "section": "Criterion D", "correct": null, "model": "Most energy is used in respiration and lost as heat [1]; some parts such as bones or roots are not eaten [1]; some food is not digested and is lost in faeces or urine [1].", "points": [{"text": "Most energy is used in respiration and lost as heat", "any": ["respiration", "heat"], "all": [], "marks": 1}, {"text": "Some parts such as bones or roots are not eaten", "any": ["not eaten", "bones", "roots", "parts"], "all": [], "marks": 1}, {"text": "Some food is not digested and is lost in faeces or urine", "any": ["faeces", "egest", "not digested", "excret", "urine", "waste"], "all": [], "marks": 1}]}], "subject": "MYP Biology", "level": "Grade 10", "unit": "MYP 5 · Biology · Ecosystems", "first": 543, "cfirst": 72, "k": 4}$j$::jsonb; t uuid := (d->'topic'->>'id')::uuid; begin
  if (d->'topic'->>'new')::boolean then
    insert into public.topics (id, subject_id, programme, name, summary, sort_order, parent_id) select t, s.id, d->'topic'->>'programme', d->'topic'->>'name', d->'topic'->>'summary', (d->'topic'->>'sort')::int, (d->'topic'->>'parent')::uuid
      from public.subjects s where s.name = 'MYP Science' on conflict (id) do nothing;
  end if;
  insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select (l->>'id')::uuid, t, l->>'title', l->>'summary', l->>'url', l->>'ext', (l->>'max')::int, (l->>'sort')::int from jsonb_array_elements(d->'lessons') l
    on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
  insert into public.lesson_specs (lesson, title, spec, updated_at) select l->>'ext', l->>'title', l->'spec', now() from jsonb_array_elements(d->'lessons') l
    on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
  if not exists (select 1 from public.materials m join jsonb_array_elements(d->'lessons') l on m.path = l->>'url') then   -- make room once: everything after the anchor moves down
    update public.materials set sort = sort + (d->>'k')::int where sort >= (d->>'first')::int;
    update public.class_materials cm set sort = cm.sort + (d->>'k')::int where cm.sort >= (d->>'cfirst')::int and cm.class_id in (select a.class_id from public.class_materials a where a.path = d->>'anchor');
  end if;
  insert into public.materials (path, lesson_id, title, kind, subject, level, unit, sort) select l->>'url', l->>'ext', l->>'title', 'lesson', d->>'subject', d->>'level', d->>'unit', (l->>'msort')::int from jsonb_array_elements(d->'lessons') l
    on conflict (path) do update set lesson_id = excluded.lesson_id, title = excluded.title, kind = excluded.kind, subject = excluded.subject, level = excluded.level, unit = excluded.unit, sort = excluded.sort;
  insert into public.class_materials (class_id, path, sort) select a.class_id, l->>'url', (l->>'csort')::int from jsonb_array_elements(d->'lessons') l join public.class_materials a on a.path = d->>'anchor' on conflict do nothing;
  insert into public.quizzes (id, topic_id, title, instructions, time_limit_minutes, max_attempts, published, show_results, category, feedback_mode, created_by)
    select (q->>'id')::uuid, t, q->>'title', q->>'instr', null, 2, true, true, 'quiz', 'hybrid', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e' from jsonb_array_elements(d->'quizzes') q
    on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, topic_id = excluded.topic_id;
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'quizzes' and column_name = 'subject') then
    update public.quizzes set subject = 'Biology' where id in (select (q->>'id')::uuid from jsonb_array_elements(d->'quizzes') q);
  end if;
  insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) select (q->>'id')::uuid, t, q->>'kind', q->>'prompt', q->'options', (q->>'marks')::int, q->>'section', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e' from jsonb_array_elements(d->'questions') q
    on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
  insert into public.question_answers (question_id, correct_option, model_answer, mark_scheme, points, explanation)
    select (q->>'id')::uuid, (q->>'correct')::int, case when q->>'kind' = 'mcq' then q->'options'->>((q->>'correct')::int) else q->>'model' end, case when q->>'kind' = 'mcq' then null else q->>'model' end,
           case when q->>'kind' = 'mcq' then null else q->'points' end, q->>'model' from jsonb_array_elements(d->'questions') q
    on conflict (question_id) do update set correct_option = excluded.correct_option, model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
  insert into public.quiz_questions (quiz_id, question_id, position) select (q->>'quiz')::uuid, (q->>'id')::uuid, (q->>'pos')::int from jsonb_array_elements(d->'questions') q
    on conflict (quiz_id, question_id) do update set position = excluded.position;
  insert into public.quiz_classes (quiz_id, class_id, published, published_at, published_by)
    select (q->>'id')::uuid, c.id, c.teacher_id = 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e', case when c.teacher_id = 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e' then now() end, case when c.teacher_id = 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e' then 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e'::uuid end
      from jsonb_array_elements(d->'quizzes') q cross join public.classes c where c.id in (select a.class_id from public.class_materials a where a.path = d->>'anchor')
    on conflict do nothing;
end $do$;
select (select count(*) from public.lessons where external_id like 'G10-BIO-ECOSYSTEMS-L%') as lessons, (select count(*) from public.lesson_specs where lesson like 'G10-BIO-ECOSYSTEMS-L%') as specs, (select count(*) from public.materials where path like '/g10-bio-ecosystems-%') as materials, (select count(*) from public.class_materials where path like '/g10-bio-ecosystems-%') as class_links, (select count(*) from public.quizzes where topic_id = 'c55b6d46-06cb-500f-aae1-cbb209a613e6' and title like '%exam-style questions') as exam_sets, (select count(*) from public.quiz_questions qq join public.quizzes q on q.id = qq.quiz_id where q.topic_id = 'c55b6d46-06cb-500f-aae1-cbb209a613e6' and q.title like '%exam-style questions') as exam_questions;
